mapper.select:
SELECT ja.id, ja.student_id, s.real_name AS student_name, s.phone AS student_phone, ja.job_id, j.job_name, ja.resume_id, ja.application_status, CASE ja.application_status WHEN 0 THEN '待处理' WHEN 1 THEN '已通过' WHEN 2 THEN '已拒绝' WHEN 3 THEN '已取消' ELSE '未知' END AS application_status_name, ja.application_time FROM job_application ja LEFT JOIN student s ON ja.student_id = s.id LEFT JOIN job j ON ja.job_id = j.id WHERE j.enterprise_id = #{enterpriseId}
AND ja.job_id = #{jobId}
AND ja.application_status = #{applicationStatus}
ORDER BY ja.application_time DESC

SELECT ja.id, ja.student_id, s.real_name AS student_name, s.phone AS student_phone, ja.job_id, j.job_name, ja.resume_id, r.resume_name AS resume_name, r.resume_file, ja.application_status, CASE ja.application_status WHEN 0 THEN '待处理' WHEN 1 THEN '已通过' WHEN 2 THEN '已拒绝' WHEN 3 THEN '已取消' ELSE '未知' END AS application_status_name, ja.application_time FROM job_application ja LEFT JOIN student s ON ja.student_id = s.id LEFT JOIN job j ON ja.job_id = j.id LEFT JOIN resume r ON ja.resume_id = r.id WHERE j.enterprise_id = #{enterpriseId}
AND ja.job_id = #{jobId}
AND ja.application_status = #{applicationStatus}
AND ( s.real_name LIKE CONCAT('%', #{keyword}, '%') OR s.major LIKE CONCAT('%', #{keyword}, '%') OR s.skills LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ja.application_time DESC
